"""Loading the cell table and carving out a holdout."""
from __future__ import annotations

import pandas as pd
from sklearn.model_selection import GroupShuffleSplit, train_test_split

from . import config

LABEL = "cover_type"


def load_cells(cfg: dict) -> pd.DataFrame:
    return pd.read_csv(config.resolve(cfg, cfg["data"]["cells"]))


def split(cfg: dict, df: pd.DataFrame):
    """Carve a holdout out of the cell table.

    `random` shuffles rows. `grouped` keeps every cell from one group on the same side,
    which is the honest option when the groups are spatial.
    """
    s = cfg["split"]
    if s["strategy"] == "grouped":
        gss = GroupShuffleSplit(n_splits=1, test_size=s["test_size"], random_state=s["seed"])
        tr, te = next(gss.split(df, df[LABEL], groups=df[s["group_column"]]))
        return df.iloc[tr].reset_index(drop=True), df.iloc[te].reset_index(drop=True)
    if s["strategy"] == "random":
        tr, te = train_test_split(
            df, test_size=s["test_size"], random_state=s["seed"], stratify=df[LABEL]
        )
        return tr.reset_index(drop=True), te.reset_index(drop=True)
    raise ValueError(f"unknown split strategy: {s['strategy']}")
"""Design-matrix construction.

Which column families are included is driven by `features:` in the config, so the same
code path builds the matrix at training time and at inference time. Keeping those two in
step matters: a model fitted on one column set cannot score a frame built with another.
"""
from __future__ import annotations

import pandas as pd

TERRAIN = [
    "elevation", "aspect", "slope",
    "horizontal_distance_to_hydrology", "vertical_distance_to_hydrology",
    "horizontal_distance_to_roadways",
    "hillshade_9am", "hillshade_noon", "hillshade_3pm",
    "horizontal_distance_to_fire_points",
]
SOIL_CODES = list(range(1, 41))
AREAS = ["rawah", "neota", "comanche_peak", "cache_la_poudre"]


def spec(cfg: dict) -> dict:
    f = cfg["features"]
    return {"terrain": bool(f["terrain"]),
            "soil_type": bool(f["soil_type"]),
            "wilderness_area": bool(f["wilderness_area"])}


def columns(cfg: dict) -> list[str]:
    sp, cols = spec(cfg), []
    if sp["terrain"]:
        cols += TERRAIN
    if sp["soil_type"]:
        cols += [f"soil_{s}" for s in SOIL_CODES]
    if sp["wilderness_area"]:
        cols += [f"area_{a}" for a in AREAS]
    return cols


def build(cfg: dict, df: pd.DataFrame) -> pd.DataFrame:
    sp = spec(cfg)
    out = pd.DataFrame(index=df.index)
    if sp["terrain"]:
        for c in TERRAIN:
            out[c] = df[c]
    if sp["soil_type"]:
        for s in SOIL_CODES:
            out[f"soil_{s}"] = (df["soil_type"] == s).astype("int8")
    if sp["wilderness_area"]:
        for a in AREAS:
            out[f"area_{a}"] = (df["wilderness_area"] == a).astype("int8")
    if out.shape[1] == 0:
        raise ValueError("feature spec selects no columns")
    return out[columns(cfg)]

