    from covertype import data
    _, holdout = data.split(cfg, cells)
    print(holdout.head(n).to_string(index=False))
    return 0


def main() -> int:
    if len(sys.argv) < 2 or sys.argv[1] in ("-h", "--help", "help"):
        print(__doc__)
        return 0
