import sys, numpy as np, pandas as pd
sys.path.insert(0,'/workspace/target')
from covertype import config, features, model
from sklearn.metrics import recall_score
cfg=config.load()
d=pd.read_csv('/workspace/target/data/covtype_cells.csv')

def proxy_lowelev():
    m=(d.elevation<2700)
    return d[m].assign(wilderness_area='cache_la_poudre'), d[~m]
def proxy_lowsoil():
    m=(d.elevation<2650)&(d.soil_type<=17)
    return d[m].assign(wilderness_area='cache_la_poudre'), d[~m]

def score(clf,c,dist):
    X=features.build(c,dist); y=dist.cover_type; p=clf.predict(X)
    cls=sorted(y.unique()); rec=recall_score(y,p,labels=cls,average=None,zero_division=0)
    r={int(k):round(float(v),3) for k,v in zip(cls,rec)}
    return r,(r.get(2,0)+r.get(3,0)+r.get(6,0))/4

def run(name,dist,train,soil,alpha,mi=200,lr=0.1):
    c=dict(cfg); c['features']={'terrain':True,'soil_type':soil,'wilderness_area':False}
    c['model']=dict(cfg['model']); c['model'].update(class_weight_alpha=alpha,max_iter=mi,learning_rate=lr)
    clf=model.fit(c,train)
    r,ba=score(clf,c,dist)
    print('%s soil=%d a=%.2f mi=%d lr=%.2f'%(name,soil,alpha,mi,lr), r, 'ba4=%.3f'%ba); sys.stdout.flush()

for name,pf in (('LOWELEV',proxy_lowelev),('LOWSOIL',proxy_lowsoil)):
    dist,train=pf()
    print(name,'dist',dist.cover_type.value_counts().to_dict(),'train n',len(train)); sys.stdout.flush()
    for soil in (True,False):
        for alpha in (1.0,1.5):
            run(name,dist,train,soil,alpha)
